﻿using System;using System.IO;using System.Runtime.InteropServices;using System.Threading;using System.Windows.Forms;using System.Drawing;
class IntegrationDebug:Form{
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct STARTUPINFO{public int cb;public string reserved,desktop,title;public uint x,y,cx,cy,xChars,yChars,fill,flags;public ushort show,reserved2;public IntPtr res2,input,output,error;}
 [StructLayout(LayoutKind.Sequential)]struct PROCESSINFO{public IntPtr process,thread;public uint pid,tid;}
 [DllImport("kernel32",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CreateProcess(string app,string cmd,IntPtr pa,IntPtr ta,bool inherit,uint flags,IntPtr env,string dir,ref STARTUPINFO si,out PROCESSINFO pi);
 [DllImport("kernel32")]static extern bool WaitForDebugEvent(IntPtr ev,uint ms);
 [DllImport("kernel32")]static extern bool ContinueDebugEvent(uint pid,uint tid,uint status);
 [DllImport("kernel32")]static extern bool ReadProcessMemory(IntPtr h,IntPtr a,byte[] b,int n,out IntPtr count);
 [DllImport("kernel32",CharSet=CharSet.Unicode)]static extern uint GetFinalPathNameByHandle(IntPtr h,System.Text.StringBuilder text,uint n,uint flags);
 Label info;string log;IntPtr ph;uint pid;
 IntegrationDebug(){Text="Диагностика запуска тренажёра";ClientSize=new Size(760,230);info=new Label{Dock=DockStyle.Fill,Font=new Font("Segoe UI",10),Padding=new Padding(12)};Controls.Add(info);log=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Integration_debug_log.txt");Shown+=(s,e)=>new Thread(Run){IsBackground=true}.Start();}
 void Log(string s){File.AppendAllText(log,DateTime.Now.ToString("O")+" "+s+Environment.NewLine);BeginInvoke(new Action(()=>info.Text=s));}
 byte[] Read(uint a,int n){byte[] b=new byte[n];IntPtr got;ReadProcessMemory(ph,new IntPtr(a),b,n,out got);return b;}uint U(uint a){return BitConverter.ToUInt32(Read(a,4),0);}
 string Msg(uint obj){try{uint str=U(obj+4),len=U(str-4);if(len>0&&len<2048)return System.Text.Encoding.Unicode.GetString(Read(str,(int)len*2));}catch{}return "";}
 void Run(){try{string folder=AppDomain.CurrentDomain.BaseDirectory;STARTUPINFO si=new STARTUPINFO{cb=Marshal.SizeOf(typeof(STARTUPINFO))};PROCESSINFO pi;if(!CreateProcess(Path.Combine(folder,"TrainerIntegrationHost.exe"),null,IntPtr.Zero,IntPtr.Zero,false,2,IntPtr.Zero,folder,ref si,out pi))throw new Exception("CreateProcess="+Marshal.GetLastWin32Error());ph=pi.process;pid=pi.pid;Log("Диагностика процесса PID "+pid+"; исходный EXE не изменяется.");IntPtr ev=Marshal.AllocHGlobal(160);while(true){if(!WaitForDebugEvent(ev,1000))continue;uint code=(uint)Marshal.ReadInt32(ev,0),epid=(uint)Marshal.ReadInt32(ev,4),tid=(uint)Marshal.ReadInt32(ev,8),resume=0x10002;if(code==6){var sb=new System.Text.StringBuilder(2048);GetFinalPathNameByHandle(new IntPtr(Marshal.ReadInt32(ev,12)),sb,2048,0);if(sb.ToString().IndexOf("WORK_TRENAGER",StringComparison.OrdinalIgnoreCase)>=0)Log("DLL base="+((uint)Marshal.ReadInt32(ev,16)).ToString("X8")+" "+sb);}
 if(code==1){uint ex=(uint)Marshal.ReadInt32(ev,12),addr=(uint)Marshal.ReadInt32(ev,24),num=(uint)Marshal.ReadInt32(ev,28);if(ex!=0x80000003){string line="Exception="+ex.ToString("X8")+" address="+addr.ToString("X8")+" firstChance="+Marshal.ReadInt32(ev,92);for(int i=0;i<num&&i<15;i++){uint par=(uint)Marshal.ReadInt32(ev,32+i*4);line+=" p"+i+"="+par.ToString("X8");if(ex==0x0eedfade){string m=Msg(par);if(m.Length>0)line+=" message="+m;}}Log(line);resume=0x80010001;}}if(code==5){Log("Process exit="+Marshal.ReadInt32(ev,12));ContinueDebugEvent(epid,tid,resume);break;}ContinueDebugEvent(epid,tid,resume);}}catch(Exception ex){Log(ex.ToString());}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.Run(new IntegrationDebug());}}
